#!/usr/bin/env bash
# Boot PX4 (NuttX) on an emulated CubePilot CubeOrange (STM32H743) in Renode.
#   ./run.sh                                   firmware/cubepilot_cubeorange_console.elf
#   ./run.sh firmware/other.elf --gdb          extra options go to Tools/renode/run.py
#
# Board model: generated by the Renode board tooling in $ARDUPILOT/Tools/renode from the CubeOrange hwdef (same MCU,
# sensors, buses and chip selects that PX4's cubepilot_cubeorange board uses). That tree is used unchanged; PX4-specific gaps
# in the models are patched from here with Renode monitor hooks (see FIXES below).
#
# Endpoints (state/CubeOrange/):
#   APM-UDS-serial5    UART7  NuttX/PX4 console (nsh)       ./console.sh
#   telnet localhost 1244      Renode monitor
set -euo pipefail
export PYTHONWARNINGS="ignore:pkg_resources is deprecated"
LAB="$(cd "$(dirname "$0")" && pwd)"
AP="${ARDUPILOT:-$LAB/ardupilot}"
PY="$LAB/.venv/bin/python"
RENODE="${RENODE:-$LAB/renode/Renode.app/Contents/MacOS/renode}"
[ -x "$RENODE" ] || RENODE="$LAB/renode/renode"
if [ ! -x "$PY" ] || [ ! -x "$RENODE" ] || [ ! -f "$AP/Tools/renode/run.py" ]; then
    echo "ArduPilot board tooling, Python env or Renode missing: run ./setup.sh first" >&2; exit 1
fi
ELF="firmware/cubepilot_cubeorange_console.elf"
if [ $# -gt 0 ] && [ "${1#-}" = "$1" ]; then ELF="$1"; shift; fi
ELF="$(cd "$(dirname "$ELF")" && pwd)/$(basename "$ELF")"
STATE="$LAB/state/CubeOrange"
mkdir -p "$STATE"
if pgrep -f "renode .*$LAB/state" >/dev/null || pgrep -f "Tools/renode/run.py CubeOrange.*$LAB/state" >/dev/null; then
    echo "this lab is already running (connect with ./console.sh, or ./stop.sh to restart)" >&2
    exit 1
fi
# not running, so any socket left behind by a killed run is stale (Renode refuses to re-create telem1.sock,
# which aborts the --exec chain before 'start' and leaves the emulation paused at 1.5 ms)
rm -f "$STATE/telem1.sock"

# SD card: the generated board creates a 256 MiB card (SdCardFromFile ... 0x10000000) but run.py formats a
# 512 MiB FAT32 image into it. NuttX compares the two (FAT total sectors vs. the
# card's CSD capacity) and refuses to mount. PX4 gets its own 256 MiB FAT32 card, attached in FIXES below.
SDIMG="$STATE/sdcard-px4.img"
if [ ! -f "$SDIMG" ]; then
    "$PY" -W ignore -c "import sys; sys.path.insert(0, sys.argv[1]); import fat_image; \
fat_image.create_image(sys.argv[2], 256 * 1024 * 1024, 32, label='PX4')" "$AP/Tools/renode" "$SDIMG"
fi

# FIXES: emulator gaps that NuttX/PX4 exercises and the board models don't handle. They run right after Renode's
# "start", so the emulation is paused while models are swapped (PX4 probes sensors ~1 s into boot).
P="$LAB/peripherals"
FIXES=(
    'mach set "ardupilot"'
    'pause'
    # IO coprocessor: the generated board runs the F100 at 60 MIPS; the real chip is 24 MHz. PX4's IO firmware
    # never sleeps (polling main loop), so every emulated MIPS is host work: 24 halves the lab's fixed cost.
    'mach set "iomcu"'
    'cpu PerformanceInMips 24'
    'mach set "ardupilot"'
    # UART IDLE storm: the USART model (AP_STM32F7_USART_Idle) raises the USART IRQ on every idle line regardless
    # of CR1.IDLEIE. NuttX's console/telemetry driver never enables
    # IDLEIE, so it never acknowledges it and up_interrupt re-enters forever after any received byte (0.03x).
    # When the driver reads ISR with IDLE set but IDLEIE off, acknowledge it the way silicon would never raise it.
    # (USART6 is skipped: PX4's px4io driver enables IDLEIE and clears IDLE itself.)
    'sysbus SetHookAfterPeripheralRead sysbus.usart2 "if offset == 0x1C and (value & 0x10) and not (self.ReadDoubleWord(0) & 0x10): self.WriteDoubleWord(0x20, 0x10); value = value & 0xFFFFFFEF"'
    'sysbus SetHookAfterPeripheralRead sysbus.usart3 "if offset == 0x1C and (value & 0x10) and not (self.ReadDoubleWord(0) & 0x10): self.WriteDoubleWord(0x20, 0x10); value = value & 0xFFFFFFEF"'
    'sysbus SetHookAfterPeripheralRead sysbus.uart7 "if offset == 0x1C and (value & 0x10) and not (self.ReadDoubleWord(0) & 0x10): self.WriteDoubleWord(0x20, 0x10); value = value & 0xFFFFFFEF"'
    'sysbus SetHookAfterPeripheralRead sysbus.uart8 "if offset == 0x1C and (value & 0x10) and not (self.ReadDoubleWord(0) & 0x10): self.WriteDoubleWord(0x20, 0x10); value = value & 0xFFFFFFEF"'
    # PWR_CR3: NuttX's USB OTG init sets USB33DEN and spins on USB33RDY (bit 26); the PWR model never sets it.
    'sysbus SetHookAfterPeripheralRead sysbus.pwr "if offset == 0x0C and (value & 0x01000000): value |= 0x04000000"'
    # IMUs: PX4's drivers need datasheet reset values and a free-running FIFO (see peripherals/*.cs).
    # Same SPI mux slots, rotations and WHO_AM_I as the generated board; only the model class changes.
    "include @$P/PX4Lab_ICM20602.cs"
    "include @$P/PX4Lab_ICM20948.cs"
    'machine UnregisterFromParent sysbus.spi4.spi4Mux.imu0'
    'machine LoadPlatformDescriptionFromString "imu0: Sensors.PX4Lab_ICM20602 @ spi4Mux 0 { rotation: 14; whoAmI: 0x12 }"'
    'machine UnregisterFromParent sysbus.spi4.spi4Mux.imu1'
    'machine LoadPlatformDescriptionFromString "imu1: Sensors.PX4Lab_ICM20948 @ spi4Mux 1 { rotation: 12; whoAmI: 0xEA; AuxiliaryCompassRotation: 10; AuxiliaryCompassHeaterInterference: \"10,30,-235\" }"'
    'machine UnregisterFromParent sysbus.spi1.spi1Mux.imu2'
    'machine LoadPlatformDescriptionFromString "imu2: Sensors.PX4Lab_ICM20948 @ spi1Mux 0 { rotation: 6; whoAmI: 0xE1 }"'
    # ADC1/2 and ADC3: PX4 does software-triggered single conversions with a 50 us EOC timeout
    # (see peripherals/PX4Lab_STM32H7_ADC.cs). Re-attach the generated board's analog feeds afterwards:
    # battery voltage (ch14) and current (ch15) from physics, 5 V rail sense (ch18).
    "include @$P/PX4Lab_STM32H7_ADC.cs"
    'machine UnregisterFromParent sysbus.adcM1S2'
    'machine LoadPlatformDescriptionFromString "adcM1S2: Analog.PX4Lab_STM32H7_ADC @ sysbus 0x40022000 { IRQ -> nvic@18 }"'
    'machine UnregisterFromParent sysbus.adc3'
    'machine LoadPlatformDescriptionFromString "adc3: Analog.PX4Lab_STM32H7_ADC @ sysbus 0x58026000"'
    'sysbus.physics FeedAnalog "sysbus.adcM1S2" 14 "voltage" 103.26224 0 3103 4'
    'sysbus.physics FeedAnalog "sysbus.adcM1S2" 15 "current" 31.1260155 0 4095 4'
    'sysbus.adcM1S2 FeedSample 49648 18 -1'
    # SD card: Renode's SDCard answers CMD8 (SEND_IF_COND, arg 0x1AA) with 0x100 - voltage accepted but without
    # echoing the 0xAA check pattern. NuttX (per the SD spec) rejects the card with -EIO.
    # RESP1 == 0x100 (idle state + ready) only occurs as that CMD8 reply, so complete the echo there.
    'sysbus SetHookAfterPeripheralRead sysbus.sdmmc "if offset == 0x14 and (value & 0xFFF) == 0x100: value = (value & 0xFFFFFF00) | 0xAA"'
    # SD data transfers: NuttX starts the data path with CMDTRANS in SDMMC_CMDR and leaves DCTRL.DTEN clear;
    # the SDMMC model's IDMA pump only arms on DTEN. Any DCTRL write that programs a block size
    # is a data-transfer setup, so set DTEN there.
    'sysbus SetHookBeforePeripheralWrite sysbus.sdmmc "if offset == 0x2C and (value & 0xF0) != 0: value |= 1"'
    # SD write completion: after every block write NuttX (CONFIG_MMCSD_SDIOWAIT_WRCOMPLETE) waits for the card to
    # release busy - a rising edge on D0 (PC8), seen through EXTI line 8 - with a 260 ms-per-block timeout. The model
    # has no D0 line, so every write waited out the full timeout: ~1 s per small file write, and param save stalled
    # for minutes behind the logger's multi-block writes. Model writes complete instantly, so when the driver unmasks
    # EXTI line 8 (the last step of arming), unmask it first and then give it the edge: card ready.
    "sysbus SetHookBeforePeripheralWrite sysbus.exti \"if offset == 0x80 and (value & 0x100): self.WriteDoubleWord(0x80, value); g = machine['sysbus.gpioPortC']; g.OnGPIO(8, False); g.OnGPIO(8, True)\""
    # swap in the 256 MiB card whose FAT matches the card's reported capacity (see SDIMG above)
    'machine UnregisterFromParent sysbus.sdmmc.sdcard'
    "machine SdCardFromFile @$SDIMG sysbus.sdmmc 0x10000000 True \"sdcard\""
    # TELEM1 (USART2, PX4 /dev/ttyS0, MAVLink 57600) as a second Unix socket; ./mavlink.sh connects to it
    "emulation CreateUnixSocketTerminal \"$STATE/telem1.sock\" \"telem1\""
    'connector Connect sysbus.usart2Host telem1'
)
# PAUSED_EXEC="cmd1;cmd2": extra monitor commands applied before the firmware runs (e.g. access logging)
IFS=';' read -r -a EXTRA <<< "${PAUSED_EXEC:-}"
for c in "${EXTRA[@]}"; do [ -n "$c" ] && FIXES+=("$c"); done
FIXES+=('start')
EXEC=()
for f in "${FIXES[@]}"; do EXEC+=(--exec "$f"); done

echo "firmware: $ELF"
echo "console:  ./console.sh        monitor: telnet localhost 1244"
# PX4's SPI driver rewrites SPI_CFG1 (DSIZE=8 bit, value 0x7, already set) before every transfer while the SPI is
# enabled; Renode's STM32H7 SPI model logs an ERROR per write (thousands per second) and ignores it, which is harmless.
# Drop just that line from the terminal. SHOW_SPI_NOISE=1 keeps it.
if [ -z "${SHOW_SPI_NOISE:-}" ]; then
    exec > >(grep --line-buffered -v "register while peripheral is enabled") 2>&1
fi
cd "$AP"
exec "$PY" -W ignore Tools/renode/run.py CubeOrange \
    --renode "$RENODE" --elf "$ELF" --state-dir "$STATE" \
    --uds --serial 5 --port 1244 --no-xterm --real-iomcu \
    --device '{"device": "ublox-gps", "port": "SERIAL3", "instance": 1}' \
    --rc-channels "${RC_CHANNELS:-1500,1500,1000,1500,1000,1000,1000,1000}" \
    "${EXEC[@]}" "$@"
# GPS:  u-blox model on UART4 (run.py port SERIAL3) = PX4 GPS1 /dev/ttyS2, positioned by the physics model
# R/C:  emulated SBUS receiver into the real IOMCU's R/C input; PX4's IO firmware decodes it.
#       RC_CHANNELS sets the startup sticks (throttle low); change live in the monitor: rcInput SetChannels "..."
